          '<pre class="shiki one-dark-pro-for-component-party" style="background-color:#0D1117;color:#abb2bf" tabindex="0"><code><span class="line"><span style="color:#7F848E;font-style:italic">&#x3C;!--Alpine JS suggests using a server-side templating engine or another frontend framework in conjunction with Alpine to do this--\x3e</span></span>\n<span class="line"></span>\n<span class="line"><span style="color:#ABB2BF">&#x3C;</span><span style="color:#E06C75">div</span></span>\n<span class="line"><span style="color:#D19A66">  x-data</span><span style="color:#ABB2BF">=</span><span style="color:#98C379">"{</span></span>\n<span class="line"><span style="color:#98C379">  name: \'John\',</span></span>\n<span class="line"><span style="color:#98C379">  age: 20,</span></span>\n<span class="line"><span style="color:#98C379">  favouriteColors: [\'green\', \'blue\', \'red\'],</span></span>\n<span class="line"><span style="color:#98C379">  isAvailable: true</span></span>\n<span class="line"><span style="color:#98C379">}"</span></span>\n<span class="line"><span style="color:#ABB2BF">></span></span>\n<span class="line"><span style="color:#ABB2BF">  &#x3C;</span><span style="color:#E06C75">p</span><span style="color:#ABB2BF">>My name is &#x3C;</span><span style="color:#E06C75">span</span><span style="color:#D19A66"> x-text</span><span style="color:#ABB2BF">=</span><span style="color:#98C379">"John"</span><span style="color:#ABB2BF">>&#x3C;/</span><span style="color:#E06C75">span</span><span style="color:#ABB2BF">>&#x3C;/</span><span style="color:#E06C75">p</span><span style="color:#ABB2BF">></span></span>\n<span class="line"><span style="color:#ABB2BF">  &#x3C;</span><span style="color:#E06C75">p</span><span style="color:#ABB2BF">>My age is &#x3C;</span><span style="color:#E06C75">span</span><span style="color:#D19A66"> x-text</span><span style="color:#ABB2BF">=</span><span style="color:#98C379">"age"</span><span style="color:#ABB2BF">>&#x3C;/</span><span style="color:#E06C75">span</span><span style="color:#ABB2BF">>&#x3C;/</span><span style="color:#E06C75">p</span><span style="color:#ABB2BF">></span></span>\n<span class="line"><span style="color:#ABB2BF">  &#x3C;</span><span style="color:#E06C75">p</span><span style="color:#ABB2BF">></span></span>\n<span class="line"><span style="color:#ABB2BF">    My favourite colors are &#x3C;</span><span style="color:#E06C75">span</span><span style="color:#D19A66"> x-text</span><span style="color:#ABB2BF">=</span><span style="color:#98C379">"favouriteColors.join(\', \')"</span><span style="color:#ABB2BF">>&#x3C;/</span><span style="color:#E06C75">span</span><span style="color:#ABB2BF">></span></span>\n<span class="line"><span style="color:#ABB2BF">  &#x3C;/</span><span style="color:#E06C75">p</span><span style="color:#ABB2BF">></span></span>\n<span class="line"><span style="color:#ABB2BF">  &#x3C;</span><span style="color:#E06C75">p</span><span style="color:#ABB2BF">>I am &#x3C;</span><span style="color:#E06C75">span</span><span style="color:#D19A66"> x-text</span><span style="color:#ABB2BF">=</span><span style="color:#98C379">"isAvailable ? \'available\' : \'not available\'"</span><span style="color:#ABB2BF">>&#x3C;/</span><span style="color:#E06C75">span</span><span style="color:#ABB2BF">>&#x3C;/</span><span style="color:#E06C75">p</span><span style="color:#ABB2BF">></span></span>\n<span class="line"><span style="color:#ABB2BF">&#x3C;/</span><span style="color:#E06C75">div</span><span style="color:#ABB2BF">></span></span>\n<span class="line"></span></code></pre>',
