          '<pre class="shiki one-dark-pro-for-component-party" style="background-color:#0D1117;color:#abb2bf" tabindex="0"><code><span class="line"><span style="color:#7F848E;font-style:italic">&#x3C;!-- x-text must be called on or inside an x-data block. --\x3e</span></span>\n<span class="line"><span style="color:#7F848E;font-style:italic">&#x3C;!-- The two could have a shared parent with x-data, or each could individually have x-data like so: --\x3e</span></span>\n<span class="line"></span>\n<span class="line"><span style="color:#ABB2BF">&#x3C;</span><span style="color:#E06C75">h1</span><span style="color:#D19A66"> x-data</span><span style="color:#ABB2BF">></span></span>\n<span class="line"><span style="color:#ABB2BF">  Welcome back, &#x3C;</span><span style="color:#E06C75">span</span><span style="color:#D19A66"> x-text</span><span style="color:#ABB2BF">=</span><span style="color:#98C379">"$store.user.username"</span><span style="color:#ABB2BF">>unknown user&#x3C;/</span><span style="color:#E06C75">span</span><span style="color:#ABB2BF">></span></span>\n<span class="line"><span style="color:#ABB2BF">&#x3C;/</span><span style="color:#E06C75">h1</span><span style="color:#ABB2BF">></span></span>\n<span class="line"></span>\n<span class="line"><span style="color:#ABB2BF">&#x3C;</span><span style="color:#E06C75">div</span><span style="color:#D19A66"> x-data</span><span style="color:#ABB2BF">></span></span>\n<span class="line"><span style="color:#ABB2BF">  &#x3C;</span><span style="color:#E06C75">h2</span><span style="color:#ABB2BF">>My Profile&#x3C;/</span><span style="color:#E06C75">h2</span><span style="color:#ABB2BF">></span></span>\n<span class="line"><span style="color:#ABB2BF">  &#x3C;</span><span style="color:#E06C75">p</span><span style="color:#ABB2BF">>Username: &#x3C;</span><span style="color:#E06C75">span</span><span style="color:#D19A66"> x-text</span><span style="color:#ABB2BF">=</span><span style="color:#98C379">"$store.user.username"</span><span style="color:#ABB2BF">>&#x3C;/</span><span style="color:#E06C75">span</span><span style="color:#ABB2BF">>&#x3C;/</span><span style="color:#E06C75">p</span><span style="color:#ABB2BF">></span></span>\n<span class="line"><span style="color:#ABB2BF">  &#x3C;</span><span style="color:#E06C75">p</span><span style="color:#ABB2BF">>Email: &#x3C;</span><span style="color:#E06C75">span</span><span style="color:#D19A66"> x-text</span><span style="color:#ABB2BF">=</span><span style="color:#98C379">"$store.user.email"</span><span style="color:#ABB2BF">>&#x3C;/</span><span style="color:#E06C75">span</span><span style="color:#ABB2BF">>&#x3C;/</span><span style="color:#E06C75">p</span><span style="color:#ABB2BF">></span></span>\n<span class="line"><span style="color:#ABB2BF">  &#x3C;</span><span style="color:#E06C75">button</span><span style="color:#D19A66"> @click</span><span style="color:#ABB2BF">=</span><span style="color:#98C379">"$store.user.updateUsername(\'Jane\')"</span><span style="color:#ABB2BF">></span></span>\n<span class="line"><span style="color:#ABB2BF">    Update username to Jane</span></span>\n<span class="line"><span style="color:#ABB2BF">  &#x3C;/</span><span style="color:#E06C75">button</span><span style="color:#ABB2BF">></span></span>\n<span class="line"><span style="color:#ABB2BF">&#x3C;/</span><span style="color:#E06C75">div</span><span style="color:#ABB2BF">></span></span>\n<span class="line"></span>\n<span class="line"><span style="color:#ABB2BF">&#x3C;</span><span style="color:#E06C75">script</span><span style="color:#ABB2BF">></span></span>\n<span class="line"><span style="color:#E5C07B">  document</span><span style="color:#ABB2BF">.</span><span style="color:#61AFEF">addEventListener</span><span style="color:#ABB2BF">(</span><span style="color:#98C379">"alpine:init"</span><span style="color:#ABB2BF">, () </span><span style="color:#C678DD">=></span><span style="color:#ABB2BF"> {</span></span>\n<span class="line"><span style="color:#E5C07B">    Alpine</span><span style="color:#ABB2BF">.</span><span style="color:#61AFEF">store</span><span style="color:#ABB2BF">(</span><span style="color:#98C379">"user"</span><span style="color:#ABB2BF">, {</span></span>\n<span class="line"><span style="color:#E06C75">      id</span><span style="color:#ABB2BF">: </span><span style="color:#D19A66">1</span><span style="color:#ABB2BF">,</span></span>\n<span class="line"><span style="color:#E06C75">      username</span><span style="color:#ABB2BF">: </span><span style="color:#98C379">"unicorn42"</span><span style="color:#ABB2BF">,</span></span>\n<span class="line"><span style="color:#E06C75">      email</span><span style="color:#ABB2BF">: </span><span style="color:#98C379">"unicorn42@example.com"</span><span style="color:#ABB2BF">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="color:#61AFEF">      updateUsername</span><span style="color:#ABB2BF">(</span><span style="color:#E06C75;font-style:italic">newUsername</span><span style="color:#ABB2BF">) {</span></span>\n<span class="line"><span style="color:#E5C07B">        this</span><span style="color:#ABB2BF">.</span><span style="color:#E06C75">username</span><span style="color:#56B6C2"> =</span><span style="color:#E06C75"> newUsername</span><span style="color:#ABB2BF">;</span></span>\n<span class="line"><span style="color:#ABB2BF">      },</span></span>\n<span class="line"><span style="color:#ABB2BF">    });</span></span>\n<span class="line"><span style="color:#ABB2BF">  });</span></span>\n<span class="line"><span style="color:#ABB2BF">&#x3C;/</span><span style="color:#E06C75">script</span><span style="color:#ABB2BF">></span></span>\n<span class="line"></span></code></pre>',
